  /* =========================================================
     DETECÇÃO DE CONHECIMENTO
     ========================================================= */

  function isKnowledgeRequest(text) {
    var normalized = normalizeText(text);

    var directQuestion =
      normalized.indexOf("o que e ") === 0 ||
      normalized.indexOf("o que significa ") === 0;

    var explanation =
      containsAny(
        normalized,
        [
          "explica",
          "explique",
          "me explica",
          "me explique",
          "definicao",
          "definir",
          "defina",
          "ensinar",
          "ensina",
          "ensine"
        ]
      );

    return (
      directQuestion ||
      explanation
    );
  }

  /* =========================================================
     DETECÇÃO DE PERGUNTA
     ========================================================= */

  function isQuestionRequest(text) {
    var normalized = normalizeText(text);

    var questionWords = [
      "como",
      "quando",
      "onde",
      "quem",
      "qual",
      "quanto",
      "pode",
      "posso",
      "sera que",
      "por que",
      "porque"
    ];

    for (
      var i = 0;
      i < questionWords.length;
      i++
    ) {
      var word =
        normalizeText(
          questionWords[i]
        );

      if (
        normalized === word ||
        normalized.indexOf(
          word + " "
        ) === 0
      ) {
        return true;
      }
    }

    return false;
  }

  /* =========================================================
     PONTUAÇÃO
     ========================================================= */

  function calculateIntentScore(
    text,
    intentName
  ) {
    var intent =
      INTENTS[intentName];

    if (!intent) {
      return 0;
    }

    var score = 0;

    score +=
      countMatches(
        text,
        intent.keywords
      ) * 3;

    score +=
      countMatches(
        text,
        intent.verbs
      ) * 2;

    score +=
      countMatches(
        text,
        intent.objects
      ) * 2;

    if (
      intentName === "create_app" &&
      isCreateAppRequest(text)
    ) {
      score += 10;
    }

    if (
      intentName === "save_memory" &&
      isSaveMemoryRequest(text)
    ) {
      score += 12;
    }

    if (
      intentName === "retrieve_memory" &&
      isRetrieveMemoryRequest(text)
    ) {
      score += 10;
    }

    if (
      intentName === "knowledge" &&
      isKnowledgeRequest(text)
    ) {
      score += 10;
    }

    if (
      intentName === "question" &&
      isQuestionRequest(text)
    ) {
      score += 8;
    }

    return score;
  }

  function calculateConfidence(
    score,
    secondScore
  ) {
    if (score <= 0) {
      return 0;
    }

    var difference =
      score - (secondScore || 0);

    var confidence =
      0.40 +
      Math.min(
        score / 30,
        0.40
      ) +
      Math.min(
        Math.max(
          difference,
          0
        ) / 30,
        0.20
      );

    return Math.min(
      Math.max(
        confidence,
        0
      ),
      1
    );
  }

