    Object.keys(checks);

  var passed = 0;

  keys.forEach(
    function (key) {
      if (checks[key]) {
        passed++;
      }
    }
  );

  var failed =
    keys.length - passed;

  return {
    verified:
      failed === 0,

    passed:
      passed,

    failed:
      failed,

    total:
      keys.length,

    checks:
      checks
  };
