        '<rect x="0" y="' +
        Math.round(height * 0.58) +
        '" width="' +
        width +
        '" height="' +
        Math.round(height * 0.42) +
        '" fill="#287fa5"/>';

      result +=
        '<path d="M0 ' +
        Math.round(height * 0.62) +
        ' Q ' +
        Math.round(width * 0.18) +
        ' ' +
        Math.round(height * 0.56) +
        ' ' +
        Math.round(width * 0.35) +
        ' ' +
        Math.round(height * 0.62) +
        ' T ' +
        width +
        ' ' +
        Math.round(height * 0.62) +
        ' L ' +
        width +
        ' ' +
        Math.round(height * 0.7) +
        ' L0 ' +
        Math.round(height * 0.7) +
        ' Z" fill="#54a9c5"/>';
